function inputMarkup(tool, item, translate) {
  const id = `op-${tool.id}-${item.id}`;
  if (item.type === 'file') return `<label class="field-label" for="${id}">${escapeHtml(translate(item.label))}<input class="tool-input" id="${id}" type="file" data-op-field="${item.id}"${item.accept ? ` accept="${escapeHtml(item.accept)}"` : ''}></label>`;
  if (item.type === 'select') return `<label class="field-label" for="${id}">${escapeHtml(translate(item.label))}<select class="tool-input" id="${id}" data-op-field="${item.id}">${item.options.map(([value, label]) => `<option value="${escapeHtml(value)}">${escapeHtml(translate(label))}</option>`).join('')}</select></label>`;
  if (item.type === 'textarea') return `<label class="field-label" for="${id}">${escapeHtml(translate(item.label))}<textarea class="tool-textarea tool-textarea--large" id="${id}" data-op-field="${item.id}" rows="5" spellcheck="false">${escapeHtml(item.value ?? '')}</textarea></label>`;
  const type = ['date', 'text', 'url', 'range'].includes(item.type) ? item.type : 'number';
  const attributes = ['number', 'range'].includes(type) ? `${type === 'number' ? ' inputmode="decimal"' : ''} step="${escapeHtml(item.step ?? (type === 'range' ? '1' : 'any'))}"${item.min !== undefined ? ` min="${item.min}"` : ''}${item.max !== undefined ? ` max="${item.max}"` : ''}` : '';
  return `<label class="field-label" for="${id}">${escapeHtml(translate(item.label))}<input class="tool-input" id="${id}" type="${type}" data-op-field="${item.id}"${attributes}${item.value !== undefined ? ` value="${escapeHtml(item.value)}"` : ''}></label>`;
}

