deviceMarkup['html-table-generator'] = (_tool, t) => `<div class="web-dev-tool" data-web-dev="table"><label class="field-label">${escapeHtml(t('Tab-separated rows'))}<textarea class="tool-textarea" data-table-input rows="8"></textarea></label><div class="calculator-grid"><label class="field-label">${escapeHtml(t('Table caption (optional)'))}<input class="tool-input" data-table-caption maxlength="160"></label><label class="field-label web-dev-tool__check"><input type="checkbox" data-table-headings checked> ${escapeHtml(t('First row contains headings'))}</label></div><div class="tool-actions"><button class="button button--primary" type="button" data-web-generate>${escapeHtml(t('Generate table'))}</button><button class="button button--ghost" type="button" data-web-reset>${escapeHtml(t('Reset'))}</button></div><section aria-label="${escapeHtml(t('Preview'))}"><h3>${escapeHtml(t('Preview'))}</h3><div class="web-dev-tool__preview" data-table-preview></div></section><label class="field-label">${escapeHtml(t('Generated code'))}<textarea class="tool-textarea" data-web-output rows="9" readonly></textarea></label><button class="button button--ghost" type="button" data-web-copy>${escapeHtml(t('Copy code'))}</button><p class="tool-status" id="op-status" role="status" aria-live="polite"></p></div>`;
deviceMarkup['pwa-manifest-generator'] = (_tool, t) => `<div class="web-dev-tool" data-web-dev="manifest"><div class="calculator-grid"><label class="field-label">${escapeHtml(t('App name'))}<input class="tool-input" data-manifest-name maxlength="80"></label><label class="field-label">${escapeHtml(t('Short name'))}<input class="tool-input" data-manifest-short maxlength="30"></label><label class="field-label">${escapeHtml(t('Description'))}<input class="tool-input" data-manifest-description maxlength="200"></label><label class="field-label">${escapeHtml(t('Start URL'))}<input class="tool-input" data-manifest-start value="/"></label><label class="field-label">${escapeHtml(t('Display mode'))}<select class="tool-input" data-manifest-display><option value="standalone">${escapeHtml(t('Standalone app'))}</option><option value="minimal-ui">${escapeHtml(t('Minimal interface'))}</option><option value="fullscreen">${escapeHtml(t('Full screen'))}</option><option value="browser">${escapeHtml(t('Browser tab'))}</option></select></label><label class="field-label">${escapeHtml(t('Theme color'))}<input class="tool-input" data-manifest-theme type="color" value="#ffffff"></label><label class="field-label">${escapeHtml(t('Background color'))}<input class="tool-input" data-manifest-background type="color" value="#ffffff"></label></div><div class="tool-actions"><button class="button button--primary" type="button" data-web-generate>${escapeHtml(t('Build code'))}</button><button class="button button--ghost" type="button" data-web-reset>${escapeHtml(t('Reset'))}</button></div><label class="field-label">${escapeHtml(t('Generated code'))}<textarea class="tool-textarea" data-web-output rows="8" readonly></textarea></label><div class="tool-actions"><button class="button button--ghost" type="button" data-web-copy>${escapeHtml(t('Copy code'))}</button><button class="button button--ghost" type="button" data-web-download hidden>${escapeHtml(t('Download manifest.json'))}</button></div><p class="tool-status" id="op-status" role="status" aria-live="polite"></p></div>`;
for (const engine of ['connect-four', 'reversi', 'checkers']) deviceMarkup[engine] = (_tool, t) => `<div class="board-game" data-board-game="${engine}"><p class="tool-hint">${escapeHtml(t('Two players share this device. Moves are not saved or uploaded.'))}</p><p class="board-game__status" data-board-status role="status" aria-live="polite"></p><div class="board-game__grid" data-board-grid role="group" aria-label="${escapeHtml(t(engine === 'connect-four' ? 'Connect Four board' : engine === 'checkers' ? 'Checkers board' : 'Reversi board'))}"></div><div class="board-game__actions"><button class="button button--primary" type="button" data-board-reset>${escapeHtml(t('New game'))}</button>${engine === 'reversi' ? `<button class="button button--ghost" type="button" data-board-pass disabled>${escapeHtml(t('Pass turn'))}</button>` : ''}</div></div>`;

deviceMarkup['screen-ruler'] = (_tool, t) => {
  const ticks = Array.from({ length: 51 }, (_, index) => {
    const x = 30 + index * 10; const height = index % 5 === 0 ? 30 : 15;
    return `<line x1="${x}" y1="${52 - height}" x2="${x}" y2="52" class="screen-ruler__tick"></line>${index % 5 === 0 ? `<text x="${x}" y="68" text-anchor="middle" class="screen-ruler__label">${index * 10}</text>` : ''}`;
  }).join('');
  return `<div class="screen-ruler"><p class="tool-hint">${escapeHtml(t('Measure CSS pixels on this display. Physical units are estimates unless you calibrate the ruler.'))}</p><svg class="screen-ruler__scale" viewBox="0 0 560 78" role="img" aria-label="${escapeHtml(t('Screen ruler'))}"><rect x="20" y="8" width="520" height="48" rx="8" class="screen-ruler__surface"></rect>${ticks}<line data-ruler-start-marker x1="70" y1="10" x2="70" y2="53" class="screen-ruler__marker"></line><line data-ruler-end-marker x1="270" y1="10" x2="270" y2="53" class="screen-ruler__marker screen-ruler__marker--end"></line></svg><div class="calculator-grid"><label class="field-label" for="screen-ruler-start">${escapeHtml(t('Start position (px)'))}<input class="tool-input" id="screen-ruler-start" data-ruler-start type="range" min="0" max="500" value="40"></label><label class="field-label" for="screen-ruler-end">${escapeHtml(t('End position (px)'))}<input class="tool-input" id="screen-ruler-end" data-ruler-end type="range" min="0" max="500" value="240"></label></div><output class="calculation-result" data-ruler-output aria-live="polite"></output><details class="screen-ruler__calibration"><summary>${escapeHtml(t('Calibrate'))}</summary><p class="tool-hint">${escapeHtml(t('Use the range controls to move the markers.'))}</p><div class="calculator-grid"><label class="field-label" for="screen-ruler-calibration-px">${escapeHtml(t('Pixels per known length'))}<input class="tool-input" id="screen-ruler-calibration-px" data-ruler-calibration-px type="number" min="0.1" max="10000" step="any" inputmode="decimal"></label><label class="field-label" for="screen-ruler-calibration-mm">${escapeHtml(t('Known length (mm)'))}<input class="tool-input" id="screen-ruler-calibration-mm" data-ruler-calibration-mm type="number" min="0.1" max="10000" step="any" inputmode="decimal"></label></div><button class="button button--ghost" type="button" data-ruler-clear-calibration>${escapeHtml(t('Clear calibration'))}</button></details><p class="tool-status" id="op-status" role="status" aria-live="polite">${escapeHtml(t('Use the range controls to move the markers.'))}</p></div>`;
};

deviceMarkup.protractor = (_tool, t) => {
  const ticks = Array.from({ length: 19 }, (_, index) => {
    const angle = index * 10; const radians = angle * Math.PI / 180; const inner = angle % 30 === 0 ? 126 : 132;
    const x1 = 160 + 140 * Math.cos(radians); const y1 = 160 - 140 * Math.sin(radians); const x2 = 160 + inner * Math.cos(radians); const y2 = 160 - inner * Math.sin(radians);
    const tx = 160 + 112 * Math.cos(radians); const ty = 160 - 112 * Math.sin(radians);
    return `<line x1="${x1.toFixed(2)}" y1="${y1.toFixed(2)}" x2="${x2.toFixed(2)}" y2="${y2.toFixed(2)}" class="digital-protractor__tick"></line>${angle % 30 === 0 ? `<text x="${tx.toFixed(2)}" y="${ty.toFixed(2)}" text-anchor="middle" class="digital-protractor__label">${angle}</text>` : ''}`;
  }).join('');
  return `<div class="digital-protractor"><p class="tool-hint">${escapeHtml(t('Set two rays to match the lines you want to measure. The angle is calculated locally.'))}</p><svg class="digital-protractor__face" viewBox="0 0 320 190" role="group" aria-label="${escapeHtml(t('Protractor'))}"><path d="M20 160 A140 140 0 0 1 300 160" class="digital-protractor__arc"></path><line x1="20" y1="160" x2="300" y2="160" class="digital-protractor__base"></line>${ticks}<line data-protractor-ray="0" x1="160" y1="160" x2="281.24" y2="90" class="digital-protractor__ray"></line><line data-protractor-ray="1" x1="160" y1="160" x2="90" y2="38.76" class="digital-protractor__ray digital-protractor__ray--second"></line><circle data-protractor-handle="0" cx="281.24" cy="90" r="7" class="digital-protractor__handle" tabindex="0" role="slider" aria-valuemin="0" aria-valuemax="180" aria-valuenow="30" aria-label="${escapeHtml(t('First ray (degrees)'))}"></circle><circle data-protractor-handle="1" cx="90" cy="38.76" r="7" class="digital-protractor__handle digital-protractor__handle--second" tabindex="0" role="slider" aria-valuemin="0" aria-valuemax="180" aria-valuenow="120" aria-label="${escapeHtml(t('Second ray (degrees)'))}"></circle><circle cx="160" cy="160" r="4" class="digital-protractor__origin"></circle></svg><div class="calculator-grid"><label class="field-label" for="protractor-angle-a">${escapeHtml(t('First ray (degrees)'))}<input class="tool-input" id="protractor-angle-a" data-protractor-angle="0" type="range" min="0" max="180" value="30"></label><label class="field-label" for="protractor-angle-b">${escapeHtml(t('Second ray (degrees)'))}<input class="tool-input" id="protractor-angle-b" data-protractor-angle="1" type="range" min="0" max="180" value="120"></label></div><output class="calculation-result" data-protractor-output aria-live="polite"></output><p class="tool-status" id="op-status" role="status" aria-live="polite">${escapeHtml(t('Drag a ray handle or use its range control.'))}</p><button class="button button--ghost" type="button" data-protractor-reset>${escapeHtml(t('Reset angle'))}</button></div>`;
};

plannerUiKeys['screen-ruler'].push('Screen ruler');
plannerUiKeys.protractor.push('Protractor');

export function opportunityToolMarkup(id, language = 'en', translations = {}, localizedTitle = '') {
  const tool = opportunityTools.find((item) => item.id === id);
  if (!tool) return '';
  const taskUi = id === 'task-list' ? taskListContent(language).ui : id === 'kanban-board' ? kanbanBoardContent(language).ui : id === 'reading-speed-test' ? readingSpeedContent(language).ui : id === 'habit-tracker' ? habitTrackerContent(language).ui : id === 'time-tracker' ? timeTrackerContent(language).ui : id === 'weekly-meal-planner' ? mealPlannerContent(language).ui : id === 'reading-log' ? readingLogContent(language).ui : {};
  const hasDedicatedUi = id === 'task-list' || id === 'kanban-board' || id === 'reading-speed-test' || id === 'habit-tracker' || id === 'time-tracker' || id === 'weekly-meal-planner' || id === 'reading-log';
  const plannerUi = generatedOpportunityCopy[language]?.ui ?? {};
  const t = (value) => plannerUi[value] ?? (hasDedicatedUi ? taskUi[value] ?? translations[value] : translations[value] ?? taskUi[value]) ?? interactionControlLocales[language]?.[value] ?? value;
  const initialValues = Object.fromEntries(tool.fields.filter((item) => item.type === 'select').map((item) => [item.id, item.value ?? item.options?.[0]?.[0]]));
  const fields = tool.fields.map((item) => {
    const initiallyVisible = !item.showWhen || Object.entries(item.showWhen).every(([field, value]) => initialValues[field] === value);
    return `<section class="calculator-card"${item.showWhen ? ` data-op-show-when="${escapeHtml(JSON.stringify(item.showWhen))}"${initiallyVisible ? '' : ' hidden'}` : ''}>${inputMarkup(tool, item, t)}</section>`;
  }).join('');
  if (deviceMarkup[tool.engine]) { const messages = tool.engine === 'task-list' ? ` data-task-messages="${escapeHtml(JSON.stringify(Object.fromEntries(taskListRuntimeKeys.map((key) => [key, t(key)]))))}"` : tool.engine === 'kanban-board' ? ` data-kanban-messages="${escapeHtml(JSON.stringify(Object.fromEntries(kanbanBoardRuntimeKeys.map((key) => [key, t(key)]))))}"` : tool.engine === 'reading-speed' ? ` data-reading-messages="${escapeHtml(JSON.stringify(Object.fromEntries(readingSpeedRuntimeKeys.map((key) => [key, t(key)]))))}"` : tool.engine === 'habit-tracker' ? ` data-habit-messages="${escapeHtml(JSON.stringify(Object.fromEntries(Object.keys(habitTrackerContent(language).ui).map((key) => [key, t(key)]))))}"` : tool.engine === 'time-tracker' ? ` data-time-messages="${escapeHtml(JSON.stringify(Object.fromEntries(Object.keys(timeTrackerContent(language).ui).map((key) => [key, t(key)]))))}"` : tool.engine === 'weekly-meal-planner' ? ` data-meal-messages="${escapeHtml(JSON.stringify(Object.fromEntries(Object.keys(mealPlannerContent(language).ui).map((key) => [key, t(key)]))))}"` : tool.engine === 'reading-log' ? ` data-reading-log-messages="${escapeHtml(JSON.stringify(Object.fromEntries(Object.keys(readingLogContent(language).ui).map((key) => [key, t(key)]))))}"` : ['css-animation', 'css-clip-path', 'css-filters'].includes(tool.engine) ? ` data-css-messages="${escapeHtml(JSON.stringify(Object.fromEntries(cssDesignUiKeys.map((key) => [key, t(key)]))))}"` : ['api-request-builder', 'html-table-generator', 'pwa-manifest-generator'].includes(tool.engine) ? ` data-web-dev-messages="${escapeHtml(JSON.stringify(Object.fromEntries(webDevUiKeys.map((key) => [key, t(key)]))))}"` : plannerUiKeys[tool.engine] ? ` data-planner-messages="${escapeHtml(JSON.stringify(Object.fromEntries(plannerUiKeys[tool.engine].map((key) => [key, t(key)]))))}"` : ''; const gameMessages = ['connect-four', 'reversi', 'checkers'].includes(tool.engine) ? ` data-board-game-messages="${escapeHtml(JSON.stringify(Object.fromEntries(boardGameUiKeys.map((key) => [key, t(key)]))))}"` : ''; return `<div class="tool-workspace opportunity-workspace" data-tool="${id}" data-op-engine="${tool.engine}"${messages}${gameMessages}>${deviceMarkup[tool.engine](tool, t, localizedTitle, language)}</div>`; }
  const specialHint = tool.engine === 'morse' ? `<p class="tool-hint">${escapeHtml(t('Use spaces between Morse letters and / between words when decoding.'))}</p>`
    : tool.engine === 'metronome' ? `<div class="tool-actions"><button class="button button--ghost" type="button" data-op-tap>${escapeHtml(t('Tap tempo'))}</button><button class="button button--primary" type="button" data-op-start>${escapeHtml(t('Start'))}</button><button class="button button--ghost" type="button" data-op-stop disabled>${escapeHtml(t('Stop'))}</button></div>`
      : tool.engine === 'sqlite-playground' ? `<p class="tool-hint"><button class="button button--ghost" type="button" data-sql-reset>${escapeHtml(t('Reset'))}</button></p>`
        : tool.engine === 'noise-generator' ? `<div class="tool-actions"><button class="button button--primary" type="button" data-device-start>${escapeHtml(t('Start'))}</button><button class="button button--ghost" type="button" data-device-stop disabled>${escapeHtml(t('Stop'))}</button></div>`
      : tool.engine === 'pixel-art' ? `<label class="field-label">${escapeHtml(t('Drawing color'))}<input class="tool-input" type="color" data-pixel-color value="#111111"></label>`
            : ['receipt', 'quotation'].includes(tool.engine) ? `<p class="tool-hint">${escapeHtml(t('Use one item per line: description, quantity, unit price.'))} ${escapeHtml(t('Values stay in this browser.'))}</p>` : '';
  const actionLabel = tool.engine === 'morse' ? 'Translate' : tool.engine === 'metronome' ? 'Set tempo' : ['receipt', 'quotation', 'cover-letter', 'business-card'].includes(tool.engine) ? 'Create document' : 'Calculate';
  const submitButton = tool.engine === 'metronome' ? '' : `<div class="tool-actions"><button class="button button--primary" type="button" data-op-calculate>${escapeHtml(t(actionLabel))}</button><button class="button button--ghost" type="button" data-op-clear>${escapeHtml(t('Clear'))}</button></div>`;
  const flashcardActions = tool.engine === 'flashcards' ? `<div class="tool-actions"><button class="button button--ghost" type="button" data-flashcard-load>${escapeHtml(t('Load saved deck'))}</button><button class="button button--ghost" type="button" data-flashcard-delete>${escapeHtml(t('Delete saved deck'))}</button></div>` : '';
  let output = ['receipt', 'quotation', 'cover-letter', 'business-card'].includes(tool.engine)
    ? `<label class="field-label" for="op-output">${escapeHtml(t('Preview'))}<textarea class="tool-textarea tool-textarea--large" id="op-output" readonly></textarea></label><div class="tool-actions"><button class="button button--ghost" type="button" data-op-copy>${escapeHtml(t('Copy text'))}</button><button class="button button--ghost" type="button" data-op-print>${escapeHtml(t('Print or save as PDF'))}</button></div>`
    : `<section class="result-block" aria-labelledby="op-result-title"><h2 id="op-result-title">${escapeHtml(t('Result'))}</h2><output class="calculation-result" id="op-output" aria-live="polite">—</output>${tool.engine === 'flashcards' ? `<section class="flashcard-study" data-flashcard-study hidden aria-live="polite"><p data-flashcard-count></p><article class="calculator-card"><h3 data-flashcard-front></h3><p data-flashcard-back hidden></p></article><div class="tool-actions"><button class="button button--ghost" type="button" data-flashcard-show>${escapeHtml(t('Show answer'))}</button><button class="button button--primary" type="button" data-flashcard-known>${escapeHtml(t('Mark as known'))}</button><button class="button button--ghost" type="button" data-flashcard-again>${escapeHtml(t('Review again'))}</button></div><div class="tool-actions"><button class="button button--ghost" type="button" data-flashcard-previous>${escapeHtml(t('Previous card'))}</button><button class="button button--ghost" type="button" data-flashcard-next>${escapeHtml(t('Next card'))}</button><button class="button button--ghost" type="button" data-flashcard-shuffle>${escapeHtml(t('Shuffle deck'))}</button><button class="button button--ghost" type="button" data-flashcard-save disabled>${escapeHtml(t('Save deck on this device'))}</button></div></section>` : ''}${tool.engine === 'latex-renderer' ? `<div class="op-latex-preview" data-latex-preview aria-live="polite"></div><a class="button button--ghost" data-op-download hidden download="usefulverse-equation.svg">${escapeHtml(t('Download .txt').replace(/\.txt$/iu, ''))}</a>` : ''}${['image-editor', 'watermark', 'id-photo', 'meme-maker', 'pixel-art'].includes(tool.engine) ? `<canvas data-image-canvas hidden></canvas><a class="button button--ghost" data-image-download hidden download="usefulverse-image.png">${escapeHtml(t('Download PNG'))}</a>` : ''}${['chart-maker', 'diagram-maker'].includes(tool.engine) ? `<svg data-op-svg viewBox="0 0 640 360" role="img" aria-label="${escapeHtml(localizedTitle || tool.title)}"></svg><a class="button button--ghost" data-op-download hidden download="usefulverse.svg">${escapeHtml(t('Download .txt').replace(/\.txt$/iu, ''))}</a>` : ''}${['svg-optimizer', 'hex-editor'].includes(tool.engine) ? `<a class="button button--ghost" data-op-download hidden download="usefulverse-output.bin">${escapeHtml(t('Download .txt').replace(/\.txt$/iu, ''))}</a>` : ''}${tool.engine === 'function-graph' ? `<svg data-function-graph viewBox="0 0 640 360" role="img"><title>${escapeHtml(localizedTitle || tool.title)}</title></svg>` : ''}${tool.engine === 'sqlite-playground' ? `<div id="op-sql-results" class="op-sql-results" aria-live="polite"></div>` : ''}${tool.engine === 'code-playground' ? `<iframe data-code-preview title="${escapeHtml(localizedTitle || tool.title)}" sandbox="allow-scripts" loading="lazy"></iframe>` : ''}<div class="tool-actions"><button class="button button--ghost" type="button" data-op-copy>${escapeHtml(t('Copy result'))}</button></div></section>`;
  output = output.replaceAll('data-op-download hidden', 'href="#op-output" data-op-download hidden').replaceAll('data-image-download hidden', 'href="#op-output" data-image-download hidden');
  return `<div class="tool-workspace opportunity-workspace" data-tool="${id}" data-op-engine="${tool.engine}"><div class="calculator-grid">${fields}</div>${specialHint}${submitButton}${flashcardActions}<p class="tool-status" id="op-status" role="status" aria-live="polite">${escapeHtml(t('Values are processed locally in this browser.'))}</p>${output}</div>`;
}
